+// Initialize disclosure widgets
+function initializeDisclosures() {
+    const triggers = document.querySelectorAll('.disclosure-trigger');
+
+    triggers.forEach((trigger) => {
+        const panel = trigger.closest('h3').nextElementSibling;
+
+        // Ensure content is visible without JavaScript (reader mode, no-JS fallback)
+        // Then hide it at init
+        trigger.setAttribute('aria-expanded', 'false');
+        panel.hidden = true;
+
+        // Toggle panel on trigger click
+        trigger.addEventListener('click', () => {
+            const isExpanded = trigger.getAttribute('aria-expanded') === 'true';
+            trigger.setAttribute('aria-expanded', String(!isExpanded));
+            panel.hidden = isExpanded;
