const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

async function testAccessibility() {
    const browser = await chromium.launch();
    const page = await browser.newPage();

    const htmlPath = path.resolve(__dirname, 'index.html');
    const htmlContent = fs.readFileSync(htmlPath, 'utf-8');

    await page.setContent(htmlContent, { waitUntil: 'load' });

    // Inject axe-core
    const axeSource = require('axe-core').source;
    await page.addScriptTag({ content: axeSource });

    // Run accessibility check
    const results = await page.evaluate(() => window.axe.run());

    await browser.close();

    // Filter violations by type
    const wcagViolations = results.violations.filter(v => !v.tags.includes('best-practice'));
    const bpViolations = results.violations.filter(v => v.tags.includes('best-practice'));

    const output = {
        summary: {
            passed: results.passes.length,
            wcagViolations: wcagViolations.length,
            bestPracticeWarnings: bpViolations.length
        },
        passes: results.passes.map(p => ({
            id: p.id,
            description: p.description
        })),
        wcag: wcagViolations.map(v => ({
            id: v.id,
            impact: v.impact,
            description: v.description,
            targets: v.nodes.map(n => n.target)
        })),
        bestPractice: bpViolations.map(v => ({
            id: v.id,
            description: v.description,
            targets: v.nodes.map(n => n.target)
        }))
    };

    console.log(JSON.stringify(output, null, 2));

    process.exit(wcagViolations.length > 0 ? 1 : 0);
}

testAccessibility().catch(err => {
    console.error('Test error:', err.message);
    process.exit(1);
});

